#!/usr/bin/env python3
# DJM-900NXS2 PLUS patcher. Generated by tools/make_patcher.py.
#
# Makes the mod from your own official DJM-900NXS2 firmware version 2.08
# UPD file, on this computer. It holds only the mod's own bytes and where
# they go, and it writes the mod only if the result is byte for byte the
# build that was tested on the mixer.
#
# Copyright (C) 2026 low trust society
# SPDX-License-Identifier: GPL-3.0-only
#
#   python3 djm900nxs2_plus_patcher.py [OFFICIAL_FILE]
#   python3 djm900nxs2_plus_patcher.py --check FILE_ON_THE_STICK

import base64
import hashlib
import io
import os
import re
import struct
import sys
import zipfile

DATA = None

KEY = bytes.fromhex("aab1abacb5b5a8b6b0b6b0ada6abaaacb5bca6ff")
OUT_DIR = "djm900nxs2_plus"
OFFICIAL_NAME = "DJM-900NXS2_208.upd"


class Refused(Exception):
    pass


def xor(data):
    key = KEY
    n = len(key)
    full = (key * (len(data) // n + 1))[:len(data)]
    return bytes(a ^ b ^ 0xFF for a, b in zip(data, full))


def _table():
    table = []
    for i in range(256):
        c = i << 8
        for _ in range(8):
            c = ((c << 1) ^ 0x1021) & 0xFFFF if c & 0x8000 else (c << 1) & 0xFFFF
        table.append(c)
    return table


TABLE = _table()


def crc16(data):
    crc = 0
    for byte in data:
        crc = ((crc << 8) & 0xFFFF) ^ TABLE[(crc >> 8) ^ byte]
    return crc


def sha256(data):
    return hashlib.sha256(data).hexdigest()


def official_bytes(raw):
    if raw[:4] == b"PK\x03\x04":
        try:
            with zipfile.ZipFile(io.BytesIO(raw)) as archive:
                names = [n for n in archive.namelist() if n.lower().endswith(".upd")]
                if len(names) == 1:
                    return archive.read(names[0])
        except zipfile.BadZipFile:
            pass
    return raw


def split(plain):
    top = plain[:0x20]
    segments, at = [], 0x24
    while at < len(plain):
        header = plain[at:at + 32]
        length = struct.unpack_from("<I", plain, at + 32)[0]
        segments.append([header, bytearray(plain[at + 36:at + 36 + length])])
        at += 38 + length
    return top, segments


def join(top, segments):
    out = bytearray(top) + struct.pack("<I", sum(len(d) for _, d in segments))
    for header, data in segments:
        out += header + struct.pack("<I", len(data)) + data + struct.pack("<H", crc16(bytes(data)))
    return xor(bytes(out))


def build_mod(official):
    if sha256(official) != DATA["stock_sha256"]:
        raise Refused("this is not the official DJM-900NXS2 firmware version 2.08 UPD file. "
                      "please provide that, unchanged. any other file is refused.")
    top, segments = split(xor(official))
    by_name = {header[10:16].decode("ascii").strip(): data for header, data in segments}
    for name, runs in DATA["changes"].items():
        data = by_name[name]
        for offset, encoded in runs:
            new = base64.b64decode(encoded)
            data[offset:offset + len(new)] = new
    top = top[:20] + DATA["tag"].encode("ascii") + top[23:]
    mod = join(top, segments)
    if sha256(mod) != DATA["mod_sha256"]:
        raise Refused("the result is not the tested build. nothing was written.")
    return mod


def version_tag(raw):
    """The version in a DJM-900NXS2 file's header ("208" for the official 2.08), or None."""
    found = re.fullmatch(rb"DJM-TOP-NEXT {4}Ver\.([0-9]{3})", xor(raw[:0x24])[:23])
    return found.group(1).decode("ascii") if found else None


def plus_version(raw):
    """"PLUS V0.91" for a file of the mod's version 0.91, as the mixer names it."""
    tag = version_tag(raw) or ""
    return "PLUS V" + tag[:1] + "." + tag[1:]


def identify(raw):
    """"mod" (the tested build), "official", "damaged" (named as this build but not it),
    "plus" (another version of the mod) or "other"."""
    digest = sha256(raw)
    if digest == DATA["mod_sha256"]:
        return "mod"
    if digest == DATA["stock_sha256"]:
        return "official"
    tag = version_tag(raw)
    if tag == DATA["tag"]:
        return "damaged"
    if tag and tag[0] == "0":
        return "plus"
    return "other"


def ask(prompt):
    try:
        return input(prompt)
    except EOFError:
        return ""


def path_from(text):
    text = text.strip()
    if len(text) >= 2 and text[0] == text[-1] and text[0] in "'\"":
        text = text[1:-1]
    return os.path.expanduser(text.replace("\\ ", " "))


def notice():
    print()
    print("unofficial and experimental [!]")
    print()
    print(DATA["notice"]["warning"])
    for point in DATA["notice"]["points"]:
        print("  - " + point)
    print()
    print("good to know")
    for point in DATA["known_issues"]:
        print("  - " + point)
    print()
    return ask("type yes if you have read this and accept the risk: ").strip().lower() == "yes"


def check(path):
    try:
        with open(path, "rb") as f:
            raw = f.read()
    except OSError as error:
        print("the file could not be read (%s)." % error)
        return False
    kind = identify(raw)
    if raw[:4] == b"PK\x03\x04":
        inside = identify(official_bytes(raw))
        if inside in ("mod", "official"):
            print("this is %s, still in its zip. the mixer cannot update from a zip: open it and copy %s "
                  "from it to the top folder of your USB stick."
                  % (("the mod", DATA["mod_name"]) if inside == "mod" else ("the official firmware 2.08", OFFICIAL_NAME)))
            return False
    folder = os.path.dirname(os.path.abspath(path))
    others = [n for n in os.listdir(folder)
              if n.lower().endswith(".upd") and n.upper().startswith("DJM-900NXS2")
              and n != os.path.basename(path)]
    ok = True
    if kind == "mod":
        print("confirmed: this is the tested build (%s). safe to update." % DATA["build"])
        if os.path.basename(path) != DATA["mod_name"]:
            print("but it is called %s: rename it to %s." % (os.path.basename(path), DATA["mod_name"]))
            ok = False
    elif kind == "official":
        print("confirmed: this is the official firmware 2.08. safe to update to go back to stock.")
        if os.path.basename(path) != OFFICIAL_NAME:
            print("but it is called %s: rename it to %s." % (os.path.basename(path), OFFICIAL_NAME))
            ok = False
    elif kind == "plus":
        print("this is %s, not %s. this patcher only checks %s."
              % (plus_version(raw), DATA["build"], DATA["build"]))
        return False
    else:
        print("this file is not right. DO NOT update with it. copy %s to the top folder of your USB "
              "stick again, eject the stick, plug it back in and try again." % DATA["mod_name"])
        return False
    if others:
        print("the stick also holds %s. keep only one DJM-900NXS2 UPD file on it." % ", ".join(sorted(others)))
        ok = False
    return ok


def steps():
    print()
    print("what's next")
    print("  1. copy %s to the top folder of a FAT32 USB stick." % os.path.join(OUT_DIR, DATA["mod_name"]))
    print("     keep only one DJM-900NXS2 UPD file on the stick.")
    print("  2. eject the stick properly, then plug it back in.")
    print("  3. drop the file from the stick into this window and press enter, to check it.")
    print("  4. update: " + DATA["update_text"])
    print("  *  going back to stock: the same steps with your official DJM-900NXS2_208.upd alone on")
    print("     the stick.")
    print()


def main(argv):
    if DATA is None:
        print("this is the template, without the mod's data.")
        return 2
    if len(argv) == 2 and argv[0] == "--check":
        return 0 if check(path_from(argv[1])) else 1
    if len(argv) > 1 or (argv and argv[0].startswith("-")):
        print("usage: python3 djm900nxs2_plus_patcher.py [OFFICIAL_FILE]")
        print("       python3 djm900nxs2_plus_patcher.py --check FILE_ON_THE_STICK")
        return 2
    print("DJM-900NXS2 PLUS patcher")
    print("you need your own official DJM-900NXS2 firmware version 2.08 UPD file and a FAT32 USB stick.")
    source = path_from(argv[0]) if argv else path_from(
        ask("drop your official DJM-900NXS2 firmware version 2.08 UPD file into this window and press enter: "))
    try:
        with open(source, "rb") as f:
            official = official_bytes(f.read())
    except OSError as error:
        print("the file could not be read (%s)." % error)
        return 1
    kind = identify(official)
    if kind == "mod":
        print("this is already the mod. nothing to build.")
        print("copy it as %s to the top folder of a FAT32 USB stick, the only DJM-900NXS2 UPD file on it."
              % DATA["mod_name"])
        print("to check it there: python3 %s --check FILE_ON_THE_STICK"
              % os.path.basename(sys.argv[0] or "djm900nxs2_plus_patcher.py"))
        return 0
    if kind == "damaged":
        print("this says it is %s, but it is not byte for byte the tested build: it is damaged or changed. "
              "DO NOT update with it. give your official 2.08 file to build it again." % DATA["build"])
        return 1
    if kind == "plus":
        print("this is already modified: %s. the mod is only built from the official "
              "DJM-900NXS2 firmware version 2.08 UPD file. please provide that, unchanged." % plus_version(official))
        return 1
    if kind != "official":
        print("this is not the official DJM-900NXS2 firmware version 2.08 UPD file. "
              "please provide that, unchanged. any other file is refused.")
        return 1
    print("official DJM-900NXS2 firmware version 2.08 UPD file detected.")
    if not notice():
        print("nothing was written.")
        return 1
    print("building the mod...")
    try:
        mod = build_mod(official)
    except Refused as error:
        print("stopped: %s" % error)
        return 1
    os.makedirs(OUT_DIR, exist_ok=True)
    target = os.path.join(OUT_DIR, DATA["mod_name"])
    with open(target, "wb") as f:
        f.write(mod)
    print("done: %s, checked: byte for byte the tested build." % os.path.abspath(target))
    print("sha-256 %s" % DATA["mod_sha256"])
    steps()
    while True:
        text = ask("file on the stick (or press enter to finish): ").strip()
        if not text:
            return 0
        check(path_from(text))


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
